int journal_unmap_buffer(journal_t *journal, struct buffer_head *bh) {
    int ret = 0;
    struct journal_head *jh;

    if (!buffer_journaled(bh))
        return 0;

    jh = journal_get_jhead(journal, bh->b_blocknr);
    if (!jh)
        return -EINVAL;

    jbd_lock_journal(journal);

    if (jh->b_transaction) {
        if (jh->b_transaction == journal->j_running_transaction) {
            if (buffer_dirty(bh)) {
                jbd_clear_dirty(jh);
                journal->j_running_transaction->t_modified = 1;
            }
            jh->b_transaction = NULL;
        } else if (jh->b_transaction->t_state == BJT_COMMIT) {
            jbd_attach_buffer_to_commit(jh);
        } else {
            jbd_zap_buffer(jh);
        }
    }

    if (buffer_dirty(bh))
        mark_buffer_clean(bh);

    jbd_unlock_journal(journal);
    jbd_put_journal_head(jh);

    return ret;
}

int journal_unmap_buffer(journal_t *journal, struct buffer_head *bh) {
    struct journal_head *jh;
    transaction_t *t;

    if (!buffer_journalled(bh))
        return 0;

    jh = get_journal_head(bh);
    if (!jh)
        return -EINVAL;

    t = jh->t;
    if (!t)
        return -EINVAL;

    spin_lock(&journal->lock);
    if (t == journal->running_transaction) {
        if (buffer_dirty(bh)) {
            spin_unlock(&journal->lock);
            return -EBUSY;
        }
        jh->b = NULL;
        spin_unlock(&journal->lock);
        brelse(bh);
        return 0;
    } else if (t == journal->committing_transaction) {
        jh->b = NULL;
        spin_unlock(&journal->lock);
        mark_buffer_clean(bh);
        return 0;
    } else {
        spin_unlock(&journal->lock);
        journal_zap_buffer(jh);
        brelse(bh);
        return 0;
    }
}

