int journal_unmap_buffer(journal_t *journal, struct buffer_head *bh) {
    struct journal_head *jh;

    if (!buffer_journalled(bh))
        return 0;

    jh = get_journal_head(bh);
    if (!jh)
        return -EINVAL;

    lock_journal(journal);

    if (jh->b_transaction && jh->b_transaction != journal->running_transaction) {
        if (jh->b_modified)
            journal_zap_buffer(jh);
        else
            journal_attach_buffer_to_commit(jh);
    } else if (jh->b_transaction == journal->running_transaction) {
        journal_dispose_buffer(jh);
    }

    clear_buffer_dirty(bh);
    clear_buffer_journalled(bh);

    unlock_journal(journal);

    return 0;
}

int journal_unmap_buffer(journal_t *journal, struct buffer_head *bh) {
    struct journal_head *jh;

    if (!buffer_journalled(bh))
        return 0;

    jh = get_journal_head(bh);
    if (!jh)
        return -1;

    lock_journal(journal);

    if (jh->b_transaction) {
        if (jh->b_transaction->t_state == TRANSACTION_RUNNING)
            jh->b_transaction = NULL;
        else if (jh->b_transaction->t_state == TRANSACTION_COMMITTING)
            attach_to_committing_transaction(jh);
        else
            dispose_buffer(jh);
    }

    clear_buffer_dirty(bh);
    clear_journal_head(jh);
    unlock_journal(journal);

    return 0;
}
